package com.sentinel.kms.ingest;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;

/**
 * Durable, server-owned source material for one ingestion job.
 *
 * <p>The source identity and revision are generated by the server.  They are
 * deliberately separate from file names, URLs and connector metadata, all of
 * which are mutable or user controlled.  Upload bytes are retained in Postgres
 * so retry/recovery never needs to synthesize replacement content.</p>
 */
@Entity
@Table(name = "ingest_job_sources")
@Getter
@Setter
@NoArgsConstructor
public class IngestSource {

    /** Hard ceiling enforced by the durable PostgreSQL BYTEA constraint. */
    static final long MAX_PERSISTED_BYTES = 20L * 1024 * 1024;

    @Id
    private String id;

    @Column(name = "job_id", nullable = false, unique = true)
    private String jobId;

    @Column(name = "source_type", nullable = false)
    private String sourceType;

    @Column(name = "source_revision_id", nullable = false)
    private String sourceRevisionId;

    @Column(name = "source_key", nullable = false, unique = true)
    private String sourceKey;

    @Column(name = "original_name")
    private String originalName;

    @Column(name = "content_type")
    private String contentType;

    @Column(name = "source_url")
    private String sourceUrl;

    /** PostgreSQL BYTEA; intentionally not stored on {@link IngestJob}. */
    @Column(name = "source_bytes")
    private byte[] sourceBytes;

    @Column(name = "source_size_bytes", nullable = false)
    private long sourceSizeBytes;

    @Column(name = "source_sha256")
    private String sourceSha256;

    public static IngestSource upload(
            String sourceId,
            String revisionId,
            String jobId,
            String name,
            String contentType,
            byte[] bytes) {
        IngestSource source = base(sourceId, revisionId, jobId, "upload", name, contentType, null);
        source.retain(bytes);
        return source;
    }

    public static IngestSource url(
            String sourceId,
            String revisionId,
            String jobId,
            String name,
            String url) {
        return base(sourceId, revisionId, jobId, "url", name, null, url);
    }

    private static IngestSource base(
            String sourceId,
            String revisionId,
            String jobId,
            String sourceType,
            String name,
            String contentType,
            String sourceUrl) {
        IngestSource source = new IngestSource();
        source.setId(sourceId);
        source.setSourceRevisionId(revisionId);
        source.setSourceKey(sourceKey(sourceId, revisionId));
        source.setJobId(jobId);
        source.setSourceType(sourceType);
        source.setOriginalName(name);
        source.setContentType(contentType);
        source.setSourceUrl(sourceUrl);
        source.setSourceSizeBytes(0);
        return source;
    }

    public boolean hasRetainedBytes() {
        return sourceBytes != null && sourceBytes.length > 0;
    }

    /** Populate upload bytes or the first successfully fetched URL response; the database permits this once per revision. */
    public void retain(byte[] bytes) {
        if (bytes == null || bytes.length == 0) {
            throw new IllegalArgumentException("Source bytes are empty");
        }
        if (bytes.length > MAX_PERSISTED_BYTES) {
            throw new IllegalArgumentException(
                    "Source exceeds durable storage limit of " + MAX_PERSISTED_BYTES + " bytes");
        }
        this.sourceBytes = bytes.clone();
        this.sourceSizeBytes = bytes.length;
        this.sourceSha256 = sha256(bytes);
    }

    public static String sourceKey(String sourceId, String revisionId) {
        return sourceId + ":" + revisionId;
    }

    static String sha256(byte[] bytes) {
        try {
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 is unavailable", e);
        }
    }
}
